import { Project } from '../../src'
import { CallExpressionShape, Plugin, type Record, VariableStatementShape } from '@servicenow/sdk-build-core'
import { ArrowFunctionShape, NowIdShape } from '@servicenow/sdk-build-plugins'

const SequencePlugin = Plugin.create({
    name: 'SequencePlugin',
    records: {
        sys_sequence: {
            coalesce: ['name'],
            relationships: {
                sys_sequence_step: {
                    via: 'sequence',
                    descendant: true,
                },
            },
            toShape(record, { descendants }) {
                const statements = descendants.query().map(
                    (d) =>
                        new CallExpressionShape({
                            source: d,
                            callee: 'Step',
                            args: [
                                d.transform(({ $, merge }) => ({
                                    $id: $.val(NowIdShape.from(d)),
                                    type: $,
                                    [merge]: $.from('args').map((args) =>
                                        Object.fromEntries(
                                            args
                                                .asString()
                                                .split(';')
                                                .map((p) => p.split(':'))
                                                .map(([k, v]) => [k, v])
                                        )
                                    ),
                                })),
                            ],
                        })
                )

                return {
                    success: true,
                    value: new CallExpressionShape({
                        source: record,
                        callee: 'Sequence',
                        args: [
                            { name: record.get('name') },
                            new ArrowFunctionShape({
                                source: record,
                                statements,
                            }),
                        ],
                    }),
                }
            },
        },
    },
    shapes: [
        {
            shape: CallExpressionShape,
            async toRecord(shape, { factory, diagnostics }) {
                if (shape.getCallee() !== 'Sequence') {
                    return { success: false }
                }

                const [config, body] = shape.getArguments()
                const name = config.asObject().get('name').asString('Config must provide a name')
                const sequence = await factory.createRecord({
                    source: shape,
                    table: 'sys_sequence',
                    explicitId: name,
                    properties: { name },
                })

                const steps: Record[] = []
                for (const statement of body.as(ArrowFunctionShape).getStatements()) {
                    const step = (statement.if(VariableStatementShape)?.getInitializer() ?? statement).ifRecord()
                    if (!step) {
                        diagnostics.error(statement, 'Unsupported statement in sequence body')
                        return { success: false }
                    }

                    steps.push(
                        step.merge({
                            sequence,
                            order: steps.length,
                        })
                    )
                }

                return {
                    success: true,
                    value: sequence.with(...steps),
                }
            },
        },
    ],
})

const StepPlugin = Plugin.create({
    name: 'StepPlugin',
    shapes: [
        {
            shape: CallExpressionShape,
            async toRecord(shape, { factory }) {
                if (shape.getCallee() !== 'Step') {
                    return { success: false }
                }

                const step = shape.getArgument(0).asObject()
                return {
                    success: true,
                    value: await factory.createRecord({
                        source: shape,
                        table: 'sys_sequence_step',
                        explicitId: step.get('$id'),
                        properties: {
                            type: step.get('type'),
                            args: Object.entries(step.omit(['$id', 'type']))
                                .map(([k, v]) => `${k}:${v.getValue()}`)
                                .join(';'),
                        },
                    }),
                }
            },
        },
    ],
})

const LIB = {
    path: 'lib.d.ts',
    content: `
declare module '@servicenow/sdk/core' {
    export function Sequence(...args: any[]): any
    export function Step(...args: any[]): any
}
`,
}

describe('Arrow Functions', () => {
    describe('Sequence Plugin', () => {
        let project: Project

        beforeEach(() => {
            project = new Project()
            project.addFile(LIB)
            project.getPlugins().prepend(StepPlugin, SequencePlugin)
        })

        test('Simple log message', async () => {
            const sequenceName = 'Log Sequence'
            const logMessage = 'Hello, world!'

            const sequenceId = project.registerCoalesceId('sys_sequence', { name: sequenceName })
            const stepId = project.registerExplicitId('sys_sequence_step', '123')

            const file = project.addFile({
                path: 'sequence.now.ts',
                content: `import { Sequence, Step } from '@servicenow/sdk/core'

const message = '${logMessage}'
Sequence({ name: '${sequenceName}' }, (_config) => {
    Step({ $id: Now.ID['123'], type: 'log', message: message })
})
`,
            })

            const diagnostics = await file.getDiagnostics()
            expect(diagnostics.map((d) => d.message)).toHaveLength(0)

            const records = await file.getRecords()
            expect(records.query()).toHaveLength(2)

            const sequence = records.get('sys_sequence', sequenceId)
            expect(sequence).toBeDefined()
            expect(sequence.get('name').getValue()).toBe(sequenceName)

            const step = records.get('sys_sequence_step', stepId)
            expect(step).toBeDefined()
            expect(step.get('sequence').equals(sequence)).toBe(true)
            expect(step.getValue()).toMatchObject({
                type: 'log',
                order: 0,
                args: `message:${logMessage}`,
            })
        })

        test('Multiple simple steps', async () => {
            const sequenceName = 'Multi-Step Sequence'
            const logMessageA = 'Hello'
            const logMessageB = 'Goodbye'
            const notificationAddress = 'admin@example.com'
            const notificationMessage = 'Greetings'

            const sequenceId = project.registerCoalesceId('sys_sequence', { name: sequenceName })
            const logIdA = project.registerExplicitId('sys_sequence_step', '123')
            const notifyId = project.registerExplicitId('sys_sequence_step', '456')
            const logIdB = project.registerExplicitId('sys_sequence_step', '789')

            const file = project.addFile({
                path: 'sequence.now.ts',
                content: `import { Sequence, Step } from '@servicenow/sdk/core'

Sequence({ name: '${sequenceName}' }, (_) => {
    Step({ $id: Now.ID['123'], type: 'log', message: '${logMessageA}' })
    Step({ $id: Now.ID['456'], type: 'notify', email: '${notificationAddress}', message: '${notificationMessage}' })
    Step({ $id: Now.ID['789'], type: 'log', message: '${logMessageB}' })
})
`,
            })

            const diagnostics = await file.getDiagnostics()
            expect(diagnostics.map((d) => d.message)).toHaveLength(0)

            const records = await file.getRecords()
            expect(records.query()).toHaveLength(4)

            const sequence = records.get('sys_sequence', sequenceId)
            expect(sequence).toBeDefined()
            expect(sequence.get('name').getValue()).toBe(sequenceName)

            const logStepA = records.get('sys_sequence_step', logIdA)
            expect(logStepA).toBeDefined()
            expect(logStepA.get('sequence')).toStrictEqual(sequence)
            expect(logStepA.getValue()).toMatchObject({
                type: 'log',
                order: 0,
                args: `message:${logMessageA}`,
            })

            const notifyStep = records.get('sys_sequence_step', notifyId)
            expect(notifyStep).toBeDefined()
            expect(notifyStep.get('sequence')).toStrictEqual(sequence)
            expect(notifyStep.getValue()).toMatchObject({
                type: 'notify',
                order: 1,
                args: `email:${notificationAddress};message:${notificationMessage}`,
            })

            const logStepB = records.get('sys_sequence_step', logIdB)
            expect(logStepB).toBeDefined()
            expect(logStepB.get('sequence')).toStrictEqual(sequence)
            expect(logStepB.getValue()).toMatchObject({
                type: 'log',
                order: 2,
                args: `message:${logMessageB}`,
            })

            const output = await file.getOutput()
            console.log(JSON.stringify(output.map(({ path, content }) => ({ path, content }))))
        })

        test('Multiple steps with outputs passed around', async () => {
            const sequenceName = 'Multi-Step Sequence'
            const logMessage = 'Hello'
            const queryTable = 'incident'
            const queryCondition = 'state=new'
            const notificationAddress = 'admin@example.com'

            const sequenceId = project.registerCoalesceId('sys_sequence', { name: sequenceName })
            const logId = project.registerExplicitId('sys_sequence_step', '123')
            const queryId = project.registerExplicitId('sys_sequence_step', '456')
            const notifyId = project.registerExplicitId('sys_sequence_step', '789')

            const file = project.addFile({
                path: 'sequence.now.ts',
                content: `import { Sequence, Step } from '@servicenow/sdk/core'

Sequence({ name: '${sequenceName}' }, (_inputs) => {
    Step({ $id: Now.ID['123'], type: 'log', message: '${logMessage}' })
    const result = Step({ $id: Now.ID['456'], type: 'query', table: '${queryTable}', query: '${queryCondition}' }) 
    Step({ $id: Now.ID['789'], type: 'notify', email: '${notificationAddress}', message: \`New incident(s): \${result}\` })
})
`,
            })

            const diagnostics = await file.getDiagnostics()
            expect(diagnostics.map((d) => d.message)).toHaveLength(0)

            const records = await file.getRecords()
            expect(records.query()).toHaveLength(4)

            const sequence = records.get('sys_sequence', sequenceId)
            expect(sequence).toBeDefined()
            expect(sequence.get('name').getValue()).toBe(sequenceName)

            const logStep = records.get('sys_sequence_step', logId)
            expect(logStep).toBeDefined()
            expect(logStep.get('sequence')).toStrictEqual(sequence)
            expect(logStep.getValue()).toMatchObject({
                type: 'log',
                order: 0,
                args: `message:${logMessage}`,
            })

            const queryStep = records.get('sys_sequence_step', queryId)
            expect(queryStep).toBeDefined()
            expect(queryStep.get('sequence')).toStrictEqual(sequence)
            expect(queryStep.getValue()).toMatchObject({
                type: 'query',
                order: 1,
                args: `table:${queryTable};query:${queryCondition}`,
            })

            const notifyStep = records.get('sys_sequence_step', notifyId)
            expect(notifyStep).toBeDefined()
            expect(notifyStep.get('sequence')).toStrictEqual(sequence)
            expect(notifyStep.getValue()).toMatchObject({
                type: 'notify',
                order: 2,
                args: `email:${notificationAddress};message:New incident(s): ${queryId}`,
            })
        })

        test('Bidirectional sync with multiple steps', async () => {
            const { changedFiles } = await project.transform([
                {
                    path: 'step0.xml',
                    content: `<?xml version="1.0"?>
<record_update table="sys_sequence_step">
  <sys_sequence_step action="INSERT_OR_UPDATE">
    <sys_id>123</sys_id>
    <args>message:Hello</args>
    <order>0</order>
    <sequence name="Generated Sequence">000</sequence>
    <type>log</type>
  </sys_sequence_step>
</record_update>`,
                },
                {
                    path: 'step1.xml',
                    content: `<?xml version="1.0"?>
<record_update table="sys_sequence_step">
  <sys_sequence_step action="INSERT_OR_UPDATE">
    <sys_id>456</sys_id>
    <args>email:admin@example.com;message:Greetings</args>
    <order>1</order>
    <sequence name="Generated Sequence">000</sequence>
    <type>notify</type>
  </sys_sequence_step>
</record_update>`,
                },
                {
                    path: 'step2.xml',
                    content: `<?xml version="1.0"?>
<record_update table="sys_sequence_step">
  <sys_sequence_step action="INSERT_OR_UPDATE">
    <sys_id>789</sys_id>
    <args>message:Goodbye</args>
    <order>2</order>
    <sequence name="Generated Sequence">000</sequence>
    <type>log</type>
  </sys_sequence_step>
</record_update>`,
                },
                {
                    path: 'sequence.xml',
                    content: `<?xml version="1.0"?>
<record_update table="sys_sequence">
  <sys_sequence action="INSERT_OR_UPDATE">
    <sys_id>000</sys_id>
    <name>Generated Sequence</name>
  </sys_sequence>
</record_update>`,
                },
            ])

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getPath()).toMatch(/src\/fluent\/generated\/other\/sys-sequence\/sequence\.now\.ts$/)
            expect(changedFiles[0].getContent()).toBe(`import { Sequence, Step } from '@servicenow/sdk/core'

Sequence(
    {
        name: 'Generated Sequence',
    },
    () => {
        Step({
            $id: Now.ID['123'],
            type: 'log',
            message: 'Hello',
        })
        Step({
            $id: Now.ID['456'],
            type: 'notify',
            email: 'admin@example.com',
            message: 'Greetings',
        })
        Step({
            $id: Now.ID['789'],
            type: 'log',
            message: 'Goodbye',
        })
    }
)
`)
        })
    })
})
